FMT_CONSTEXPR20 auto format_unsigned(UInt value) -> char* {
  auto n = static_cast<detail::uint32_or_64_or_128_t<UInt>>(value);
  return detail::do_format_decimal(buffer_, n, buffer_size - 1);
}

